/* ===================== BANNERS =====================
 * Limited-time rate-up events. Banner defs (id, name, cardIds) ship bundled
 * as DATELESS templates — the live schedule comes from a remote JSON file
 * (see background.js → BANNER_SCHEDULE_URL, published via BannerPress).
 *
 * To prepare a new banner: add the exclusive cards above (exclusive: true)
 * and register the banner here WITHOUT dates. Publish the schedule with
 * BannerPress when it should go live.
 */
const BANNERS = [
  {
    id: "banner-001",
    name: "Mina's Dog",
    cardIds: ["s09", "l06", "b11"]  // exclusive card id(s) — 50/50 rate-up per tier
  },
  {
    id: "banner-002",
    name: "Censor",
    cardIds: ["l07", "s10", "b12"]
  },
  {
    id: "banner-003",
    name: "Knight",
    cardIds: ["s11", "b13", "b14", "s12", "l08", "b15"]
  },
  {
    id: "banner-004",
    name: "Gym",
    cardIds: ["l09", "s13", "b16", "s14", "b17", "b18"]
  }

];

// the banner live right now, else null.
// `schedule` = remote payload { bannerId, startsAt, endsAt } (content.js
// passes its cached mirror; background.js passes its own cache).
// No schedule / unknown id / outside the window → no active banner.
function activeBanner(now = Date.now(), schedule = null) {
  if (!schedule || !schedule.bannerId) return null;
  const tpl = BANNERS.find(b => b.id === schedule.bannerId);
  if (!tpl) return null;
  const start = Date.parse(schedule.startsAt);
  const end = Date.parse(schedule.endsAt);
  if (Number.isNaN(start) || Number.isNaN(end)) return null;
  if (now < start || now >= end) return null;
  return { ...tpl, startsAt: schedule.startsAt, endsAt: schedule.endsAt };
}

// Cloudinary transform applied to served URLs (compressed card-size WebP)
const CARD_IMG_TRANSFORM = "w_450,q_auto,f_auto";

function _hexToBytes(hex) {
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(hex.substr(i * 2, 2), 16);
  return out;
}

function _b64ToBytes(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < out.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

let _cardKeyPromise = null;
function _getCardKey() {
  if (!_cardKeyPromise) {
    const keyBytes = _hexToBytes(KEY_P1 + KEY_P2 + KEY_P3);
    _cardKeyPromise = crypto.subtle.importKey("raw", keyBytes, { name: "AES-GCM" }, false, ["decrypt"]);
  }
  return _cardKeyPromise;
}

// Apply the Cloudinary transform to a base upload URL:
//   .../image/upload/v123/file.png → .../image/upload/w_450,q_auto,f_auto/v123/file.png
function cardImageUrl(baseUrl) {
  return baseUrl.replace("/image/upload/", "/image/upload/" + CARD_IMG_TRANSFORM + "/");
}

/**
 * Decrypt all card URLs.
 * Returns a map: { id → { id, name, tier, url } } with transformed URLs ready to render.
 * Runs once at overlay open; result should be cached by the caller.
 */
async function decryptCards() {
  const key = await _getCardKey();
  const out = {};
  await Promise.all(ENCRYPTED_CARDS.map(async (card) => {
    try {
      const raw = _b64ToBytes(card.enc);
      const iv = raw.slice(0, 12);
      const ct = raw.slice(12);
      const plain = await crypto.subtle.decrypt({ name: "AES-GCM", iv }, key, ct);
      const baseUrl = new TextDecoder().decode(plain);
      out[card.id] = { id: card.id, name: card.name, tier: card.tier, url: cardImageUrl(baseUrl), exclusive: !!card.exclusive, passive: card.passive || null, unlock: card.unlock || null };
    } catch (e) {
      console.warn("cards.js: failed to decrypt card", card.id, e);
    }
  }));
  return out;
}
